import React, { useEffect, useState, useRef } from 'react';
import io from 'socket.io-client';
import Header from './Header';
import { Form, InputGroup, Button } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPaperPlane } from '@fortawesome/free-solid-svg-icons';
import ChatBlock from './ChatBlock';

const Chat = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [user, setUser] = useState(null);
  const socket = useRef();

  const token = localStorage.getItem('token');
  //   const [typingMessage, setTypingMessage] = useState('');
  const [typingUsers, setTypingUsers] = useState([]);
  const messagesEndRef = useRef();

  function formatTypingMessage(users) {
    const count = users.length;
    let exists = users.includes(user.username)
    if (count === 0) return '';
    if (count === 1) return `${users[0] === user.username ? '' : `${users[0]} is typing...`}`;
    // if (count === 2) return `${users[0] === user.username ? `${users[1]} is typing...` : `${users[0]} is typing...`}`;
    if (count >= 2)
      return `${users[0]}, ${users[1]}, and ${count - 1} others are typing...`;
  }

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {

    scrollToBottom();

    if (!token) return;

    // Connect to backend
    socket.current = io('http://localhost:4000', {
      auth: {
        token
      }
    });

    // Fetch user info
    fetch('http://localhost:4000/api/auth/me', {
      headers: { 'x-auth-token': token }
    }).then(res => res.json()).then(userData => {
      setUser(userData);
    });

    socket.current.on("updateTypingUsers", (users) => {
      setTypingUsers(users);
    });

    // socket.current.on("userTyping", (msg) => {
    // setTypingMessage(msg);

    // // Clear typing message after 3 seconds
    // setTimeout(() => {
    //   if (typingMessage === msg) {
    //     setTypingMessage('');
    //   }
    // }, 2000);
    // });

    socket.current.on("receiveMessage", (message) => {
      // console.log("📨 Message received:", message);
      setMessages(prev => [...prev, message]);
    });

    socket.current.on('userList', (users) => {
      console.log('Current users online:', users);
    });

    // // Listen for messages
    // socket.current.on('authenticated', () => {
    //     console.log('auth')
    //   socket.current.on('receiveMessage', (msg) => {
    //     setMessages(prev => [...prev, msg]);
    //   });

    //   socket.current.on('userList', (users) => {
    //     console.log('Current users online:', users);
    //   });
    // });

    socket.current.on('unauthorized', () => {
      alert('Authentication failed!');
      window.location.href = '/signin';
    });

    return () => {
      socket.current.disconnect();
    };

  }, [token, messages]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message.trim()) return;

    const fullMessage = {
      text: message,
      username: user.username,
      time: new Date().toLocaleTimeString()
    };
    socket.current.emit('sendMessage', fullMessage);

    socket.current.emit('stopTyping', user.username); // Clear typing status
    setMessage('');
  };

  return (
    <>
      <div>
        <Header username={user?.username} />
        {/* <ChatBlock messages={messages} user={user} typingUsers={typingUsers} messagesEndRef={messagesEndRef}/> */}
        <div style={{
          height: '80vh',
          maxHeight: '80vh',
          border: '1px solid #ccc',
          overflowY: 'auto',
          padding: '10px'
        }}>
          <ChatBlock messages={messages}/>
          {/* {messages.map((msg, i) => {
            const isMyMessage = msg.username === user?.username;
            return (
              <div
                key={i}
                style={{
                  display: 'flex',
                  justifyContent: isMyMessage ? 'flex-end' : 'flex-start',
                  marginBottom: '10px'
                }}>
                <div
                  style={{
                    backgroundColor: isMyMessage ? '#007bff' : '#f1f1f1',
                    color: isMyMessage ? 'white' : 'black',
                    padding: '10px 15px',
                    borderRadius: '10px',
                    maxWidth: '60%',
                    wordWrap: 'break-word'
                  }}>
                  <strong >{msg.username}</strong><br />
                  <span><span style={{ paddingRight: '12px' }} >{msg.text}</span><small style={{ fontSize: '9px' }} >{msg.time}</small></span>
                </div>
              </div>
            );
          })} */}
          <div ref={messagesEndRef} />
          {typingUsers.length > 0 && (
            <div style={{ fontStyle: 'italic', color: '#666', marginBottom: '5px' }}>
              {formatTypingMessage(typingUsers)}
            </div>
          )}
        </div>
        {/* input Label */}
        <Form onSubmit={sendMessage}>
          <InputGroup className="mb-3">
            <Form.Control
              placeholder="Write a message..."
              aria-label="Write a message..."
              aria-describedby="basic-addon2"
              value={message}
              onChange={(e) => {
                setMessage(e.target.value);
                // if (e.target.value.trim() !== '') {
                //     socket.current.emit('typing', user.username);
                // }}
                if (e.target.value.trim() !== '') {
                  socket.current.emit('typing', user.username); // Notify others
                } else {
                  socket.current.emit('stopTyping', user.username); // Stop typing
                }
              }}
            />
            {/* <FontAwesomeIcon icon="fa-solid fa-paper-plane" /> */}
            <Button type='submit' style={{width:'60px'}}>
              <FontAwesomeIcon icon={faPaperPlane} />
            </Button>
          </InputGroup>
        </Form>
      </div>
    </>
  );
};

export default Chat;
